css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .74); position: relative; }
.loader .kick { position: absolute; left: 30%; bottom: 4%; width: 40%; height: 38%; border-radius: 50%; background: radial-gradient(circle at 40% 34%, color-mix(in srgb, #fff 25%, var(--accent)), var(--accent)); box-shadow: inset 0 0 0 4px var(--accent-2); animation: kit-kick calc(var(--loader-speed) * 1.2) ease-out infinite; }
.loader .snare { position: absolute; left: 6%; bottom: 30%; width: 30%; height: 14%; border-radius: 50%; background: linear-gradient(color-mix(in srgb, #fff 35%, var(--accent-2)), var(--accent-2)); animation: kit-snare calc(var(--loader-speed) * 1.2) ease-out infinite; }
.loader .hat { position: absolute; right: 6%; bottom: 44%; width: 32%; height: 9%; border-radius: 50%; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 25%, var(--accent-2))); animation: kit-hat calc(var(--loader-speed) * .6) ease-out infinite; }
.loader .stick { position: absolute; bottom: 46%; width: 30%; height: 5%; border-radius: 3px; background: linear-gradient(90deg, #e2e8f0, #94a3b8); }
.loader .stick:nth-of-type(4) { left: 4%; transform-origin: 10% 50%; animation: kit-stick-left calc(var(--loader-speed) * 1.2) ease-in-out infinite; }
.loader .stick:nth-of-type(5) { right: 4%; transform-origin: 90% 50%; animation: kit-stick-right calc(var(--loader-speed) * .6) ease-in-out infinite; }
@keyframes kit-kick { 0%, 100% { transform: scale(1); } 8% { transform: scale(1.09); } 24% { transform: scale(.98); } }
@keyframes kit-snare { 0%, 46%, 100% { transform: scaleY(1); } 54% { transform: scaleY(1.5); } 66% { transform: scaleY(.9); } }
@keyframes kit-hat { 0%, 100% { transform: scaleY(1); } 12% { transform: scaleY(.5); } 34% { transform: scaleY(1.15); } }
@keyframes kit-stick-left { 0%, 40%, 100% { transform: rotate(-6deg); } 52% { transform: rotate(-34deg); } }
@keyframes kit-stick-right { 0%, 100% { transform: rotate(6deg); } 20% { transform: rotate(32deg); } }
